import 'dart:io';
import 'dart:isolate';

import 'package:path/path.dart' as p;

import '../models.dart';
import 'source_editors.dart';

const aiAssistantGeneratedMarker =
    '// Generated by miniprogram embed init --ai-assistant. Do not edit.';

const _dartTemplates = [
  'host_ai.dart',
  'host_ai_actions.dart',
  'host_ai_bubble.dart',
  'host_ai_coordinator.dart',
  'host_ai_goal_sheet.dart',
  'host_ai_http_model.dart',
  'host_ai_interaction.dart',
  'host_ai_model.dart',
  'host_ai_progress.dart',
  'host_ai_root.dart',
  'host_ai_runner.dart',
  'host_ai_session.dart',
  'host_ai_settings.dart',
  'host_ai_workspace.dart',
];

Future<String> _template(String name) async {
  final uri = await Isolate.resolvePackageUri(
    Uri.parse(
      'package:mini_program_tooling/src/host_integration/embedding/ai_assistant/templates/$name.template',
    ),
  );
  if (uri == null ||
      uri.scheme != 'file' ||
      !await File.fromUri(uri).exists()) {
    throw MiniProgramEmbeddingInitException(
      'Missing installed --ai-assistant template: $name. Reinstall mini_program_tooling.',
    );
  }
  return File.fromUri(uri).readAsString();
}

Future<String> buildHostAiNativeRelay(String packageName) async =>
    '$aiAssistantGeneratedMarker\n${(await _template('HostAiSessionRelay.kt')).replaceAll('__HOST_PACKAGE__', packageName)}';

Future<Map<String, String>> planAiAssistant({
  required String projectRootPath,
  required Map<String, String> pendingWrites,
}) async {
  final root = p.join(projectRootPath, 'lib', 'mini_program');
  final files = <String, String>{
    p.join(root, 'mini_program_ai.dart'):
        "$aiAssistantGeneratedMarker\nexport 'ai/host_ai.dart';\n",
    for (final name in _dartTemplates)
      p.join(root, 'ai', name):
          '$aiAssistantGeneratedMarker\n${await _template(name)}',
  };
  for (final entry in files.entries) {
    final file = File(entry.key);
    if (await file.exists() &&
        !(await file.readAsString()).startsWith(aiAssistantGeneratedMarker)) {
      throw MiniProgramEmbeddingInitException(
        'Refusing to overwrite unrecognized assistant file ${file.path}. '
        'Move customizations to app_ai_setup.dart or reconcile it before retrying.',
      );
    }
  }
  final settings = File(p.join(root, 'app_ai_setup.dart'));
  return {
    ...files,
    if (!await settings.exists())
      settings.path: await _template('app_ai_setup.dart'),
    ...await planHostAiBuilder(
      projectRootPath: projectRootPath,
      pendingWrites: pendingWrites,
    ),
  };
}
